// HTTP routes of the UI bridge (shared module, so every server that vendors it serves the same paths):
//   GET  /bridge/push/config          -> which platforms the server can deliver to (+ VAPID public key)
//   POST /bridge/push/register        -> {platform: fcm|apns|webpush, token | subscription, profileId, scope?, preview?, quiet?, tz?, locale?}
//   POST /bridge/push/unregister      -> {id} | {platform, token | endpoint, profileId?}
//   GET  /bridge/push/registrations   -> the caller's registrations (no tokens)
//   POST /bridge/push/test            -> {id?} send a test notification to the caller's devices
// Authentication is done by the host service (`authenticate(req)` -> {user} | null). Bodies are small JSON.
// Canonical copy: push/src (see scripts/sync-push.sh).
import { isHexToken } from './apns.mjs';
import { parseSettings, publicRegistration } from './store.mjs';
import { validSubscription } from './webpush.mjs';

export const PUSH_PREFIX = '/bridge/push/';
const BODY_MAX = 16 * 1024;

function readJson(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (c) => {
      size += c.length;
      if (size > BODY_MAX) {
        reject(Object.assign(new Error('too large'), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on('end', () => {
      try {
        resolve(chunks.length ? JSON.parse(Buffer.concat(chunks).toString('utf8')) : {});
      } catch {
        reject(Object.assign(new Error('invalid JSON'), { status: 400 }));
      }
    });
    req.on('error', reject);
  });
}

/** FCM tokens: opaque, ~150-200 chars of [A-Za-z0-9_:-]. */
const validFcmToken = (t) => typeof t === 'string' && /^[A-Za-z0-9_:\-.]{20,4096}$/.test(t);

/**
 * @param {{store: any, notifier: any, publicConfig: () => object, webpushHosts?: string[],
 *   validateScope?: (user: string, scope: object) => {ok: true, value: object} | {ok: false, message: string},
 *   sendJson: (res: any, status: number, body: any) => void}} o
 */
export function createPushRoutes(o) {
  const err = (res, status, message, code) => o.sendJson(res, status, { error: { message, type: 'invalid_request_error', code: code ?? null } });

  async function register(req, res, user, credential) {
    const body = await readJson(req);
    const platform = body.platform;
    const settings = parseSettings(body);
    if (!settings.ok) return err(res, 400, settings.message);
    let scope = settings.value.scope;
    if (o.validateScope) {
      const v = o.validateScope(user, scope);
      if (!v.ok) return err(res, 403, v.message, 'scope_not_allowed');
      scope = v.value;
    }
    const rec = { user, platform, ...settings.value, scope, enabled: true };
    if (typeof credential === 'string' && credential) rec.credential = credential; // revocation binding (H3)
    if (platform === 'webpush') {
      if (!validSubscription(body.subscription, o.webpushHosts ?? [])) return err(res, 400, 'subscription must be a PushSubscription JSON with an https endpoint of a known push service');
      rec.subscription = { endpoint: body.subscription.endpoint, keys: { p256dh: body.subscription.keys.p256dh, auth: body.subscription.keys.auth } };
    } else if (platform === 'fcm') {
      if (!validFcmToken(body.token)) return err(res, 400, 'token must be an FCM registration token');
      rec.token = body.token;
    } else if (platform === 'apns') {
      if (!isHexToken(body.token)) return err(res, 400, 'token must be a hex APNs device token');
      rec.token = body.token.toLowerCase();
      if (body.apnsEnvironment === 'sandbox' || body.apnsEnvironment === 'production') rec.apnsEnv = body.apnsEnvironment;
    } else return err(res, 400, "platform must be 'fcm'|'apns'|'webpush'");
    const cfg = o.publicConfig();
    if (!cfg.platforms?.[platform]) return err(res, 409, `${platform} is not configured on this server`, 'platform_not_configured');
    const saved = o.store.upsert(rec);
    o.sendJson(res, 200, { object: 'hui.push.registration', registration: publicRegistration(saved) });
  }

  async function unregister(req, res, user) {
    const body = await readJson(req);
    let n = 0;
    if (typeof body.id === 'string') n = o.store.remove({ user, id: body.id });
    else if (body.platform === 'webpush' && typeof body.endpoint === 'string') n = o.store.remove({ user, platform: 'webpush', deviceKey: body.endpoint, profileId: body.profileId });
    else if ((body.platform === 'fcm' || body.platform === 'apns') && typeof body.token === 'string') {
      n = o.store.remove({ user, platform: body.platform, deviceKey: body.platform === 'apns' ? body.token.toLowerCase() : body.token, profileId: body.profileId });
    } else return err(res, 400, 'need {id} or {platform, token|endpoint}');
    o.sendJson(res, 200, { object: 'hui.push.unregistered', removed: n });
  }

  return {
    matches: (path) => path.startsWith(PUSH_PREFIX),
    /**
     * Handle an authenticated request; `user` is the caller's id, `credential` an opaque id of the authenticating
     * token/device (never the secret itself) that new registrations are bound to.
     */
    async handle(req, res, user, path, credential) {
      try {
        const sub = path.slice(PUSH_PREFIX.length);
        if (req.method === 'GET' && sub === 'config') return o.sendJson(res, 200, { object: 'hui.push.config', ...o.publicConfig() });
        if (req.method === 'POST' && sub === 'register') return await register(req, res, user, credential);
        if (req.method === 'POST' && sub === 'unregister') return await unregister(req, res, user);
        if (req.method === 'GET' && sub === 'registrations') {
          return o.sendJson(res, 200, { object: 'list', data: o.store.forUser(user).map(publicRegistration) });
        }
        if (req.method === 'POST' && sub === 'test') {
          const body = await readJson(req);
          const results = await o.notifier.test(user, typeof body.id === 'string' ? body.id : undefined);
          return o.sendJson(res, 200, { object: 'hui.push.test', results });
        }
        return err(res, 404, 'not found', 'not_found');
      } catch (e) {
        if (res.headersSent) return res.destroy();
        return err(res, e?.status ?? 500, e?.status ? e.message : 'push error');
      }
    },
  };
}
